import {stageParameters} from './model.js?v=20261017-5';
import {validTrial,readLocal,writeLocal} from './trial-state.js?v=20261018-20';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const terms={
 '黏聚力':{symbol:'c · kPa',text:'用来描述土体抗剪强度中的黏聚贡献。在本模型中，黏聚抗力为 c × L。',hint:'初始工况保留黏聚项；后续滑动界面工况取 c = 0。',type:'bond'},
 '内摩擦角':{symbol:'φ · °',text:'反映土体摩擦抗剪特性的参数。法向作用项相同时，tanφ 越大，摩擦抗力越大。',hint:'它是材料强度参数，与滑面的几何倾角 β 不同。',type:'friction'},
 '滑面倾角':{symbol:'β · °',text:'滑动界面与水平方向的夹角，用于计算沿坡与法向的作用分量。',hint:'拖动 β 时，受力图中的滑面方向也会变化。',type:'slope'},
 '浮容重':{symbol:'γ′ = γsat − γw',text:'饱和土容重减去水的容重，用于表达浮力影响下的有效重量。',hint:'网页渗流工况采用 γ′ = 20 − 9.8 = 10.2 kN/m³，并按该工况公式计入渗流作用系数。',type:'water'},
 '容重':{symbol:'γ · kN/m³',text:'单位体积土体的重量。含水条件不同，模型采用天然、饱和或浮容重。',hint:'在这份二维计算中，容重与所选截面面积一起确定土体自重项 W。',type:'weight'},
 '抗滑力':{symbol:'R · kN',text:'沿滑面抵抗滑动的作用。本模型的总抗滑项由黏聚抗力与摩擦抗力组成。',hint:'绿色箭头表示 R，可与相同绘图尺度的下滑项 T 比较。',type:'balance'},
 '下滑力':{symbol:'T · kN',text:'沿滑面推动土体滑动的作用，来自自重及当前工况计入的车辆荷载。',hint:'红色箭头表示 T。参数如何进入 T，以当前显示的工况公式为准。',type:'balance'},
 '安全系数':{symbol:'Fₛ = R / T',text:'用抗滑项除以下滑项，比较模型中两者的大小。',hint:'Fₛ > 1 表示有抗滑余量，Fₛ = 1 为极限平衡，Fₛ < 1 表示存在滑动趋势。',type:'balance'},
 '渗流':{symbol:'水在土体孔隙中运动',text:'水沿土体孔隙运动的过程，水的作用会改变土体与界面的受力条件。',hint:'蓝色流线帮助辨认过程与方向；具体数值按渗流工况公式计算。',type:'water'}
};
function diagram(type){
 const base='<path d="M25 145L215 145L215 164H25Z" fill="#d9c49e"/><rect x="77" y="82" width="96" height="58" rx="3" fill="#a7c3ad" stroke="#53765e" stroke-width="2"/>';
 const body=type==='water'?'<path d="M25 65Q65 55 105 65T215 65V155H25Z" fill="#c5e0dc"/><path d="M25 91Q65 81 105 91T215 91M25 119Q65 109 105 119T215 119" stroke="#5b9ba3" fill="none" stroke-width="3"/><rect x="88" y="77" width="70" height="66" fill="#afbd9d"/><path d="M124 27V65M124 156V122" stroke="#426b73" stroke-width="4"/><text x="38" y="185">水的作用与土体重量</text>':type==='bond'?base+'<path d="M86 134V152M109 134V152M132 134V152M155 134V152" stroke="#a57e35" stroke-width="4"/><text x="75" y="191">黏聚抗力 cL</text>':type==='slope'?'<path d="M30 70L210 160H30Z" fill="#dac59e"/><path d="M30 70L210 160" stroke="#b88043" stroke-width="4"/><path d="M30 70H120M92 70Q94 88 86 98" stroke="#87612d" fill="none"/><text x="100" y="98">β</text><text x="53" y="188">倾角描述几何条件</text>':base+(type==='weight'?'<path d="M125 30V72M115 60L125 72L135 60" stroke="#526b76" fill="none" stroke-width="4"/><text x="105" y="24">W</text><text x="62" y="190">容重 × 截面面积</text>':'<path d="M74 114H29M42 104L29 114L42 124" stroke="#327861" fill="none" stroke-width="4"/><path d="M174 114H224M212 104L224 114L212 124" stroke="#ac5b43" fill="none" stroke-width="4"/><text x="33" y="94">R</text><text x="206" y="94">T</text><text x="48" y="190">'+(type==='friction'?'摩擦抗力 N* tanφ':'抗滑与下滑的比较')+'</text>');
 return `<svg viewBox="0 0 250 210" role="img" aria-label="概念示意，几何不按比例">${body}</svg>`;
}
export function setupReadingTools({applyTrial}){
 const glossary=document.createElement('dialog');glossary.id='glossary-dialog';glossary.className='content-dialog glossary-dialog';glossary.setAttribute('aria-labelledby','glossary-title');glossary.innerHTML='<button type="button" class="close-dialog" aria-label="关闭术语解释">×</button><p class="eyebrow">一句话读懂</p><h2 id="glossary-title"></h2><div id="glossary-picture"></div><strong id="glossary-symbol"></strong><p id="glossary-definition"></p><p id="glossary-hint"></p><div class="glossary-index">'+Object.keys(terms).map(term=>`<button type="button" data-term="${term}">${term}</button>`).join('')+'</div>';document.body.append(glossary);glossary.querySelector('.close-dialog').addEventListener('click',()=>glossary.close());
 const dictionary=document.createElement('div');dictionary.className='glossary-entry';dictionary.innerHTML='<span>遇到陌生概念？带虚线下划线的词可以点开解释。</span><button type="button" data-term="安全系数">打开力学词卡 ↗</button>';$('#explore .plain-language').after(dictionary);
 function openTerm(term){const value=terms[term];if(!value)return;$('#glossary-title').textContent=term;$('#glossary-symbol').textContent=value.symbol;$('#glossary-definition').textContent=value.text;$('#glossary-hint').textContent=value.hint;$('#glossary-picture').innerHTML=diagram(value.type);glossary.querySelectorAll('[data-term]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.term===term)));if(!glossary.open)glossary.showModal();}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-term]');if(b){e.preventDefault();openTerm(b.dataset.term);}});
 const matcher=new RegExp(Object.keys(terms).sort((a,b)=>b.length-a.length).join('|'),'g');
 function annotate(root){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement.closest('button,a,svg,output,script,style')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);let used=0;for(const node of nodes){if(used>=2)break;matcher.lastIndex=0;const matches=[...node.textContent.matchAll(matcher)];if(!matches.length)continue;const fragment=document.createDocumentFragment();let end=0;for(const match of matches){if(used>=2)break;fragment.append(node.textContent.slice(end,match.index));const b=document.createElement('button');b.type='button';b.className='glossary-term';b.dataset.term=match[0];b.textContent=match[0];b.setAttribute('aria-label','解释'+match[0]);fragment.append(b);end=match.index+match[0].length;used++;}fragment.append(node.textContent.slice(end));node.replaceWith(fragment);}}
 $$('.care-rows details p,.hero-description,.range-label>span,.section-heading p').forEach(annotate);
 document.addEventListener('model-part-select',()=>annotate($('#structure-detail')));
 const sections=['home','story','model-comparison','explore','lab','evidence','care','paper','references','wishes'];const old=readLocal('guitu-session-v1'),oldTrial=validTrial(old?.trial),oldReading=old?.reading&&sections.includes(old.reading.id)&&Number.isFinite(old.reading.fraction)&&old.reading.fraction>=0&&old.reading.fraction<=1?old.reading:null;const baseline=stageParameters(0),hasTrial=oldTrial&&(oldTrial.stage!==0||Object.keys(oldTrial.params).some(k=>Math.abs(oldTrial.params[k]-baseline[k])>1e-7));let currentTrial=null,playback=false,timer,pending=Boolean(hasTrial||oldReading&&oldReading.id!=='home');
 const resume=document.createElement('aside');resume.id='resume-prompt';resume.className='resume-prompt';resume.hidden=!pending;resume.innerHTML='<div><strong>继续上次的探索</strong><span>阅读位置和试算条件保存在此浏览器。</span></div><div><button type="button" id="resume-reading">继续阅读</button><button type="button" id="resume-trial">恢复上次试算</button><button type="button" id="resume-dismiss" class="text-link">从头阅读</button><button type="button" id="resume-clear" class="text-link">清除记录</button></div>';$('main').prepend(resume);$('#resume-reading').disabled=!oldReading;$('#resume-trial').disabled=!oldTrial;
 function readingPosition(){const line=100;let target=$('#home');for(const id of sections){const el=$('#'+id);if(el&&el.getBoundingClientRect().top<=line)target=el;}const rect=target.getBoundingClientRect();return {id:target.id,fraction:Math.max(0,Math.min(1,(-rect.top)/Math.max(1,rect.height)))};}
 let clearing=false;
 function persist(){if(clearing||pending||$('dialog[open]'))return;writeLocal('guitu-session-v1',{version:1,reading:readingPosition(),trial:currentTrial});}
 function queueSave(){clearTimeout(timer);timer=setTimeout(persist,500);}
 function finishResume(){pending=false;resume.hidden=true;}
 $('#resume-reading').addEventListener('click',()=>{if(!oldReading)return;finishResume();requestAnimationFrame(()=>{const target=$('#'+oldReading.id);scrollTo({top:scrollY+target.getBoundingClientRect().top+target.getBoundingClientRect().height*oldReading.fraction,behavior:'instant'});queueSave();});});
 $('#resume-trial').addEventListener('click',()=>{if(!oldTrial)return;finishResume();applyTrial(oldTrial);$('#lab-form').scrollIntoView({behavior:'instant',block:'start'});queueSave();});$('#resume-dismiss').addEventListener('click',()=>{finishResume();queueSave();});$('#resume-clear').addEventListener('click',()=>{clearing=true;clearTimeout(timer);finishResume();try{localStorage.removeItem('guitu-session-v1');localStorage.removeItem('guitu-trials-v1');}catch{}location.reload();});
 addEventListener('scroll',queueSave,{passive:true});addEventListener('pagehide',persist);document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();});document.addEventListener('stage-playback-change',e=>playback=e.detail.active);
 document.addEventListener('lab-calculated',e=>{currentTrial=validTrial(e.detail);if((Object.hasOwn(e.detail.params,e.detail.changed)||e.detail.changed==='restore')&&!playback){pending=false;resume.hidden=true;}annotate($('#stage-description'));annotate($('#lab-control-note'));queueSave();});
}
